#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

/* Read exactly one text line, with or without a final newline. */
static int read_value(long *out)
{
    char line[64];
    size_t used = 0;
    int ch;
    int invalid = 0;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || ch > CHAR_MAX || used == sizeof line - 1) {
            invalid = 1;
        } else {
            line[used++] = (char)ch;
        }
    }
    if (invalid || ferror(stdin) || used == 0) {
        return 0;
    }
    line[used] = '\0';

    char *end;
    errno = 0;
    long value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE) {
        return 0;
    }
    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return 0;
    }
    *out = value;
    return 1;
}

int main(void)
{
    long value;
    if (!read_value(&value)) {
        puts("invalid");
        return 0;
    }

    int below = value < 20;
    int above = value > 70;
    fprintf(stderr, "value %ld below %d above %d\n", value, below, above);
    puts(below || above ? "invalid" : "accepted");
    return 0;
}

